// The boss ladder as DATA. It is generated by tools/gen_ladders.py, a stand-in until
// phase 2 brings the real one, so the failure mode is a level outside the curve or a
// boss with no sprite -- and a bad dex number here is an out-of-bounds read into
// TS_DEX_TBL, not a strange-looking opponent.
#include "Arduino.h"
#include "roster.h"
#include "trainers.h"
#include "noart.h"
#include <cstdio>
#include <cstring>
#ifndef TAMA_NATIVE_TEST
uint32_t g_seed=1; FakeSerial Serial; FakeESP ESP; FakeWire Wire;
volatile int g_touchX=0,g_touchY=0; volatile bool g_touchDown=false; bool wasPressed=false;
uint32_t millis(){return 0;} void FakeESP::restart(){exit(0);}
int FakeSerial::available(){return 0;} String FakeSerial::readStringUntil(char){return String("");}
void sfxPlay(uint8_t){}
#endif
#define MAX_LEVEL_FOR_TEST 100
static int bad=0;
static void ck(bool ok,const char*w){printf("%s  %s\n",ok?"PASS":"FAIL",w); if(!ok)bad++;}

int main(){
  int oob=0, badLvl=0, noName=0, falls=0, noArt=0, dup=0;
  uint8_t prev=0;
  for (int i=0;i<TRAINER_COUNT;i++){
    const Trainer &t = TRAINERS[i];
    if (!t.name || !t.name[0] || !t.place || !t.place[0]) noName++;
    // the one that would actually crash: TS_DEX_TBL has DEX_COUNT+1 entries
    if (!dexValid((int16_t)t.dex)) { oob++; continue; }
    if (strcmp(TS_DEX_TBL[t.dex].name, t.name)) noName++;
    if (t.level < 1 || t.level > MAX_LEVEL_FOR_TEST) badLvl++;
    if (t.level < prev) falls++;
    prev = t.level;
    if (!speciesHasArt((int16_t)t.dex)) {
      printf("      %s: dex %d has no sprite\n", t.name, (int)t.dex);
      noArt++;
    }
    for (int j=0;j<i;j++) if (TRAINERS[j].dex==t.dex) dup++;
    if (t.level != TS_BOSS_TBL[i].level) badLvl++;
  }
  ck(oob==0, "every boss is a real dex number");
  ck(badLvl==0, "every boss has the level of its slot in TS_BOSS_TBL");
  ck(noName==0, "every boss is named after its form, and placed");
  ck(falls==0, "the ladder only climbs");
  ck(dup==0, "and nobody appears on it twice");
  // noart.h and the ladder are generated separately, so nothing else connects them:
  // a boss with no art would put a bare dex number on screen.
  ck(noArt==0, "no boss is a creature with no sprite art");
  ck(!speciesHasArt(1), "and speciesHasArt really does reject an art-less dex");
  ck(TRAINERS[TRAINER_COUNT-1].level >= TRAINERS[TRAINER_COUNT-2].level, "the champion tops the ladder");
  printf("%s\n", bad?"FAILURES":"all good");
  return bad?1:0;
}
